/usr/bin/bash -lc "out=/workspace/final_answer/run_manifest.tsv
printf 'bioproject\\trun_accession\\tlibrary_layout\\tforward_path\\treverse_path\\n' > \""'$out"
for acc in PRJNA1354216 PRJNA1339024; do
  awk -F'"'\\t' -v OFS='\\t' -v acc=\""'$acc" '"'
    NR==1 {for(i=1;i<=NF;i++) col["'$i]=i; next}
    {
      run=$(col["run_accession"]); layout=$(col["library_layout"]);
      if (layout=="PAIRED") {fwd="reads/" run "_1.fastq.gz"; rev="reads/" run "_2.fastq.gz";}
      else {fwd="reads/" run ".fastq.gz"; rev="";}
      print $(col["bioproject"]), run, layout, fwd, rev
    }
  '"' \"/workspace/final_answer/metadata/"'${acc}.tsv" >> "$out"
done
wc -l "$out"
sed -n '"'1,25p' \""'$out"'

